// Optional while EVALUATION_ENABLED=false. Required by judge() before admission.
// Resource bindings and required secrets are generated by `wrangler types`.
interface Env {
 EVALUATION_OPENROUTER_KEY?: string;
 GRAFANA_OTLP_AUTH?: string;
 GRAFANA_OTLP_BASE_URL?: string;
 GRAFANA_OTLP_INSTANCE_ID?: string;
 GRAFANA_INGEST_TOKEN?: string;
}
